#!/usr/bin/env node
// Generates docs/FINANCE_REVIEW.md: every decision rule and assumed default
// in the skills, collected in one place for a finance professional to review.
//
// The numeric cutoffs in the skills' `### Decision rules` tables and the
// `[ASSUMPTION]` rows in their `### Assumptions` tables are judgment calls.
// They make the output consistent; this sheet exists so someone qualified can
// confirm they are also right. Regenerated by `npm pretest`, so it always
// reflects the current skills.
//
// Usage: node scripts/generate-review-sheet.mjs

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { SPECIALISTS, SPECIALISTS_DIR, DATA_DIR } from "../extensions/money-desk/registry.mjs";
import { CALCULATORS } from "../extensions/money-desk/calculators.mjs";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(REPO, "docs", "FINANCE_REVIEW.md");

function section(md, heading) {
    const m = md.match(new RegExp(`^### ${heading}\\s*$`, "m"));
    if (!m) return "";
    const rest = md.slice(m.index + m[0].length);
    const end = rest.search(/^#{2,3} \S/m);
    return (end === -1 ? rest : rest.slice(0, end)).trim();
}

// Keep only the table rows that state a default the skill supplies itself.
function assumedRows(assumptions) {
    const lines = assumptions.split("\n");
    const header = lines.findIndex((l) => /^\|.*\|\s*$/.test(l));
    if (header === -1) return "";
    const rows = lines.slice(header + 2).filter((l) => /^\|/.test(l) && /\[ASSUMPTION/.test(l));
    return rows.length ? [lines[header], lines[header + 1], ...rows].join("\n") : "";
}

const facts = JSON.parse(readFileSync(join(DATA_DIR, "facts-2026.json"), "utf8"));
const defaults = facts.behavioral_assumptions_safe_defaults;
const calcBySkill = Object.fromEntries(Object.entries(CALCULATORS).filter(([, c]) => c.skill.startsWith("md_")).map(([k, c]) => [c.skill, k]));

const out = [
    "# Finance review sheet",
    "",
    "> Generated by `scripts/generate-review-sheet.mjs` (runs in `npm pretest`). Do not edit by hand — change the skill, then regenerate.",
    "",
    "Every skill decides with explicit numeric rules so that the same inputs always give the same recommendation. Those rules, and the defaults used when a user has no view, are **judgment calls made while standardising the skills — they have not been reviewed by a licensed professional.** This sheet lists all of them so a reviewer can confirm or correct each one.",
    "",
    "## How to review",
    "",
    "1. For each skill below, read the **Decision rules** (what the skill recommends and when) and the **Assumed defaults** (values it uses when the user gives none).",
    "2. Mark the skill in the sign-off table: ✅ agree, ✏️ change (say what), ❓ needs discussion.",
    "3. To change a rule, edit that skill's `SKILL.md`. If the skill is listed with a calculator, change the same rule in `extensions/money-desk/calculators.mjs` in the same commit — the calculator implements the table.",
    "",
    "Statutory figures (tax brackets, limits, IRS tables) are **not** on this sheet; they live in `extensions/money-desk/data/facts-2026.json` with their primary sources.",
    "",
    "## Shared modelling defaults",
    "",
    "Used by many skills when the user has no view (`md_facts` → `behavioral_assumptions_safe_defaults`). Values are fractions: 0.06 = 6%.",
    "",
    "| Default | Value |",
    "|---|---|",
    ...Object.entries(defaults)
        .filter(([k]) => !k.startsWith("_"))
        .map(([k, v]) => `| \`${k}\` | ${typeof v === "number" ? v : v} |`),
    "",
    "## Sign-off",
    "",
    "| Specialist | Skill | Calculator | Reviewer | Status | Notes |",
    "|---|---|---|---|---|---|",
];

const body = [];
let count = 0;
for (const spec of SPECIALISTS) {
    body.push("", `## ${spec.domain}`, "");
    for (const skill of spec.skills) {
        const path = join(SPECIALISTS_DIR, spec.name, "skills", skill.id.replaceAll("_", "-"), "SKILL.md");
        if (!existsSync(path)) continue;
        const md = readFileSync(path, "utf8").replace(/\r\n/g, "\n");
        const tool = `${spec.prefix}_skill_${skill.id}`;
        const calc = calcBySkill[tool];
        const rules = section(md, "Decision rules");
        const assumed = assumedRows(section(md, "Assumptions"));
        out.push(`| ${spec.domain} | ${skill.displayName} | ${calc ? `\`${calc}\`` : "—"} |  |  |  |`);
        body.push(
            `### ${skill.displayName}`,
            "",
            `\`${spec.name}/skills/${skill.id.replaceAll("_", "-")}/SKILL.md\`${calc ? ` · implemented in code by \`md_calc\` → \`${calc}\`` : ""}`,
            "",
            "**Decision rules**",
            "",
            rules || "_None found._",
            "",
            "**Assumed defaults**",
            "",
            assumed || "_None — every value comes from the user or a statutory source._",
            "",
        );
        count++;
    }
}

writeFileSync(OUT, [...out, ...body].join("\n").replace(/\n{3,}/g, "\n\n") + "\n", "utf8");
console.log(`generate-review-sheet: wrote docs/FINANCE_REVIEW.md (${count} skills)`);
